"rules": [
"Path is takes/<place>/<battle-type>/<file-name>-<portrait|landscape>.mp4. Portrait and landscape files of one take sit side by side in the same folder; there are never portrait/ or landscape/ folders.",
"Lowercase letters, numbers and hyphens only, with no spaces (the Studio turns any other character into '-').",
"Subject first, then detail, with the orientation LAST as -portrait or -landscape: king-rex-fire-breath-zoom-in-portrait.mp4.",
"If the name already exists, the Studio adds -t2, -t3 and so on before the orientation (rifleman-mirror-8v8-t2-portrait.mp4). It never overwrites.",
"Write 'vs' as vs. Write counts as 8v8 with YOU (Green) first and CPU (Tan) second: m-gunner-vs-crawler-3v20-portrait.mp4.",
"Write units with the Studio's tile names as slugs: m-gunner, radio-man, scout-jeep, heavy-tank, v2-dogfighter, emperor-bear. Write a Sarge as sarge-<iron> (sarge-saber) and THEIR SARGE as their-sarge-<iron>. The 'Bearnaparte' tile is written emperor-bear-boss, because Wyatt banned that name.",
"Keep the whole file name under about 60 characters and drop filler words (the, a, of).",
"Each clip has one home: file it under the FIRST battle type in this order that fits: intros-and-spotlights, place-features, boss-fights, sarge-battles, air-battles, weather-and-events, traps-and-terrain, story-moments, outnumbered, mirror-matches, unit-matchups, large-battles. Tags cover everything else. At Mom Alert Mom is in every fight, so file by the other subject (a Sarge fight goes in sarge-battles).",
"The place folder is whatever was picked in the Studio door. A Night or Snowfall event does not change it; night-carpet is only for elite levels 101-200.",
"A map that silently turns into a RANDOM map is never a place folder: the benched OPEN FIELD, THE BED, THE SEASIDE VILLAGE, THE FARM VILLAGE, THE FROZEN TUNDRA and THE STARSHIP, plus THE HAUNTED LIBRARY after 11/01. That is why Tundra is not on the list.",
"The Studio saves a take as <date_time>_<scene>-<frame>.mp4 in studio/takes/. Rename it to its checklist name when you move it into takes/<place>/<battle-type>/, and give the .voice.m4a stem the same base name, next to its mp4.",
"Campaign-type places (raids, parks, campaign levels and Mom Alert) have no CPU AIR, no Paratroopers (theirs) or Bomber Run (theirs), and no Mine FOR CPU. Their CPU column is the level's tan figures, which ignore UNIT LEVEL."
],
"unavailable": [
"Open Field, The Bed, The Seaside Village, The Farm Village, The Frozen Tundra and The Starship are benched in the game, so the Studio quietly loads a random map instead.",
"The Haunted Library is a Halloween map (Oct 1 to Nov 1). Picked now, it also turns into a random map.",
"Other raids and parks (Sky Fortress, Pirate Cove, Turkey Hunt, Gnome Park as a park, Nutcracker, Chess Set and more) are in the game but not in the Studio door yet."
],
