"notes": "Press T (VOICE-OVER) before R. Suggested line: 'Three stories up. One step past the eaves and you're gone. That's the roof law.' The roof fall waits for PLAY, so it fires just AFTER the battle-start timer, not during the freeze. It takes the man nearest the middle of the shot, so keep the frame centred on him at 7 s.",
